import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/api/api_client.dart';import '../../core/api/models.dart';import '../today/today_screen.dart';
final debtsProvider=FutureProvider<List<DebtDto>>((r)=>r.watch(apiClientProvider).debts());
class DebtsScreen extends ConsumerWidget{const DebtsScreen({super.key});@override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('Долги')),body:r.watch(debtsProvider).when(data:(items)=>items.isEmpty?const Center(child:Text('Долгов нет')):ListView(padding:const EdgeInsets.all(16),children:items.map((d)=>Card(child:ListTile(title:Text(d.name),subtitle:Text('${d.type} · ${(d.rateBps/100).toStringAsFixed(2)}% · платёж ${money(d.minimumPayment,d.currency)}'),trailing:Text(money(d.balance,d.currency)))).toList()),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e'))));}
